select event_month, purchase_duration_sec, duration_sec_range from (select month(event_time) as event_month, sum(case when event_type = 'purchase' then duration_sec else 0 end) as purchase_duration_sec, max(duration_sec) - min(duration_sec) as duration_sec_range from web_events group by month(event_time)) as s where purchase_duration_sec < 71 order by duration_sec_range, purchase_duration_sec desc;
